// Minimal SignaturePad implementation with endStroke event support
(function(global){
  function SignaturePad(canvas, opts){
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.penColor = (opts && opts.penColor) || '#000';
    this.minWidth = (opts && opts.minWidth) || 1;
    this.maxWidth = (opts && opts.maxWidth) || 3;
    this._empty = true;
    this._drawing = false;
    this._listeners = {};
    var self = this;

    function pos(e){
      var r = canvas.getBoundingClientRect();
      var ratio = canvas.width / r.width;
      var src = e.touches ? e.touches[0] : e;
      return {x: (src.clientX - r.left) * ratio, y: (src.clientY - r.top) * ratio};
    }
    function down(e){
      e.preventDefault();
      self._drawing = true;
      self._empty = false;
      var p = pos(e);
      self.ctx.beginPath();
      self.ctx.moveTo(p.x, p.y);
    }
    function move(e){
      if(!self._drawing) return;
      e.preventDefault();
      var p = pos(e);
      self.ctx.strokeStyle = self.penColor;
      self.ctx.lineWidth = self.maxWidth;
      self.ctx.lineCap = 'round';
      self.ctx.lineJoin = 'round';
      self.ctx.lineTo(p.x, p.y);
      self.ctx.stroke();
    }
    function up(e){
      if(!self._drawing) return;
      self._drawing = false;
      self._emit('endStroke');
    }

    canvas.addEventListener('mousedown', down);
    canvas.addEventListener('mousemove', move);
    canvas.addEventListener('mouseup', up);
    canvas.addEventListener('mouseleave', up);
    canvas.addEventListener('touchstart', down, {passive:false});
    canvas.addEventListener('touchmove', move, {passive:false});
    canvas.addEventListener('touchend', up);
  }

  SignaturePad.prototype._emit = function(event){
    var handlers = this._listeners[event] || [];
    for(var i = 0; i < handlers.length; i++) handlers[i]();
  };

  SignaturePad.prototype.addEventListener = function(event, handler){
    if(!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(handler);
  };

  SignaturePad.prototype.removeEventListener = function(event, handler){
    if(!this._listeners[event]) return;
    this._listeners[event] = this._listeners[event].filter(function(h){ return h !== handler; });
  };

  SignaturePad.prototype.clear = function(){
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this._empty = true;
  };

  SignaturePad.prototype.isEmpty = function(){ return this._empty; };

  SignaturePad.prototype.toDataURL = function(type){ return this.canvas.toDataURL(type || 'image/png'); };

  // toData / fromData stubs for resize handler compatibility
  SignaturePad.prototype.toData = function(){ return null; };
  SignaturePad.prototype.fromData = function(){ };

  global.SignaturePad = SignaturePad;
})(window);
